#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll r, g, b;
    cin >> r >> g >> b;

    ll answer = 0;
    for (ll x = 0; x <= min({2LL, r, g, b}); ++x) {
        answer = max(answer, x + (r - x) / 3 + (g - x) / 3 + (b - x) / 3);
    }

    cout << answer << '\n';
    return 0;
}

